using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B4PolishApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LayoutPolish/";const string A="Assets/Afrer_Seconds/05.Model/",P=A+"Props/B4/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");return s;}
 public static object Import(){Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=new Dictionary<string,Material>();foreach(var f in Directory.GetFiles(A+"Environment/B4/Materials","B4O_*.mat").Concat(Directory.GetFiles(P+"Materials","BX_*.mat"))){var m=AssetDatabase.LoadAssetAtPath<Material>(f.Replace('\\','/'));mats[m.name]=m;}
 foreach(string k in new[]{"Coat","Steel","Red","Paper","Dark","Warm"}){string n="BP_"+k,mp=P+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!m){m=new Material(mats["B4O_"+k]){name=n};AssetDatabase.CreateAsset(m,mp);}if(k=="Steel"){m.SetFloat("_Metallic",.82f);m.SetFloat("_Smoothness",.40f);}if(k=="Coat"){m.SetColor("_BaseColor",new Color(.32f,.34f,.35f));m.SetFloat("_Metallic",.25f);m.SetFloat("_Smoothness",.30f);}mats[n]=m;EditorUtility.SetDirty(m);}
 mats["B4O_Warm"]=mats["BP_Warm"];
 var manifest=JObject.Parse(File.ReadAllText(H+"models.json"));var catalog=new List<object>();
 foreach(var j in manifest.Properties()){string path=P+j.Name+".fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();var g=AssetDatabase.LoadAssetAtPath<GameObject>(path);var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var rr in rs.Skip(1))b.Encapsulate(rr.bounds);catalog.Add(new{model=j.Name,asset=path,size=V(b.size),center=V(b.center),triangles=g.GetComponentsInChildren<MeshFilter>().Sum(f=>f.sharedMesh.triangles.Length/3),missing=rs.Sum(r=>r.sharedMaterials.Count(m=>!m))});}
 var oldWarm=AssetDatabase.LoadAssetAtPath<Material>(A+"Environment/B4/Materials/B4O_Warm.mat");oldWarm.SetColor("_Color",Color.white);EditorUtility.SetDirty(oldWarm);AssetDatabase.SaveAssets();File.WriteAllText(H+"catalog.json",JsonConvert.SerializeObject(catalog,Formatting.Indented));return catalog;
 }
 public static object Geometry(){var s=Check();var list=new List<object>();foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)&&t.gameObject.activeInHierarchy)){
 string asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!asset.Contains("/Props/")&&!asset.Contains("ObservationDeck")&&!asset.Contains("AccessStair"))continue;var rs=t.GetComponentsInChildren<MeshFilter>();bool first=true;Bounds b=default;foreach(var mf in rs)foreach(var q in mf.sharedMesh.vertices){var v=t.InverseTransformPoint(mf.transform.TransformPoint(q));if(first){b=new Bounds(v,Vector3.zero);first=false;}else b.Encapsulate(v);}list.Add(new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,asset,p=V(t.position),e=V(t.eulerAngles),size=V(b.size),center=V(b.center),parent=t.parent?t.parent.name:"",lights=t.GetComponentsInChildren<Light>().Length});}File.WriteAllText(H+"geometry.json",JsonConvert.SerializeObject(list,Formatting.Indented));return new{items=list.Count};}
 static Transform Find(string id){if(!GlobalObjectId.TryParse(id,out var gid))throw new Exception(id);return GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as Transform;}
 static GameObject Place(JToken p,Transform parent){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)p["asset"]),parent);g.name=(string)p["name"];g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);if((bool?)p["collider"]==true){var c=g.AddComponent<BoxCollider>();c.center=V(p["center"]);c.size=V(p["size"]);}foreach(var t in g.GetComponentsInChildren<Transform>()){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);}return g;}
 public static object Run(){var s=Check();var plan=JObject.Parse(File.ReadAllText(H+"changes.json"));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;if(root.Find("B4_LayoutPolish"))throw new Exception("Already applied; use targeted repairs");
 foreach(var d in plan["disable"]){var t=Find((string)d);if(!t)throw new Exception("Missing disabled target");t.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);}
 foreach(var p in plan["moves"]){var t=Find((string)p["id"]);if(!t)throw new Exception("Missing moved target");t.SetPositionAndRotation(V(p["worldPosition"]),Quaternion.Euler(0,(float)p["yaw"],0));PrefabUtility.RecordPrefabInstancePropertyModifications(t);}
 var group=new GameObject("B4_LayoutPolish");group.transform.SetParent(root,false);var parents=new Dictionary<string,Transform>();foreach(var r in plan["rooms"]){var g=new GameObject("B4_"+(string)r["id"]+"_ServiceAndDetail");g.transform.SetParent(group.transform,false);g.transform.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);parents[(string)r["id"]]=g.transform;}
 foreach(var p in plan["add"]){Transform parent=p["parentId"]!=null?Find((string)p["parentId"]):parents[(string)p["room"]];if(!parent)throw new Exception("Missing detail parent");Place(p,parent);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{moves=plan["moves"].Count(),disabled=plan["disable"].Count(),added=plan["add"].Count(),scene=s.path};File.WriteAllText(H+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
